#!/usr/bin/env node
/**
 * bump-ios-build.js — bump the iOS build number ahead of an Xcode archive.
 *
 * App Store Connect rejects re-uploads of the same build number, so this must
 * run before every TestFlight upload. mobile/ios is generated by
 * `expo prebuild`, so the number lives in app.json (expo.ios.buildNumber) and
 * prebuild writes it into Info.plist as CFBundleVersion.
 *
 * Usage:
 *   npm run bump:ios            # +1 to the build number
 *   npm run bump:ios -- 1.0.1   # also set the version (CFBundleShortVersionString)
 *
 * Then: npx expo prebuild -p ios --clean, and archive in Xcode.
 */
const fs = require('fs');
const path = require('path');

const APP_JSON = path.resolve(__dirname, '..', 'app.json');
const config = JSON.parse(fs.readFileSync(APP_JSON, 'utf8'));
const { expo } = config;

const version = process.argv[2];
if (version && !/^\d+\.\d+\.\d+$/.test(version)) {
  console.error(`Version must look like 1.2.3, got "${version}"`);
  process.exit(1);
}

const before = `${expo.version} (${expo.ios.buildNumber})`;
expo.ios.buildNumber = String(Number(expo.ios.buildNumber || 0) + 1);
if (version) expo.version = version;

fs.writeFileSync(APP_JSON, JSON.stringify(config, null, 2) + '\n');
console.log(`iOS ${before} → ${expo.version} (${expo.ios.buildNumber})`);
